// Saves generated bytes as a file download (a PDF or spreadsheet made in the browser)
export function downloadFile(bytes: Uint8Array, filename: string, mimeType: string): void {
  const url = URL.createObjectURL(new Blob([bytes as BlobPart], { type: mimeType }));
  const link = document.createElement("a");
  link.href = url;
  link.download = filename;
  document.body.appendChild(link);
  link.click();
  link.remove();
  // Give the browser a moment to start the download before the link is freed
  setTimeout(() => URL.revokeObjectURL(url), 2000);
}
